    export const getContentAddDocumentUrl = (centerId: string,
    params: ContentAddDocumentParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/v1/centers/${centerId}/content/documents?${stringifiedParams}` : `/v1/centers/${centerId}/content/documents`
}

